"""Stage 95: the behaviour chapter (docs/61, generated by tools/analyze_behaviour_docs.py) is current, covers every behaviour of `36`, every frame class of the dispatcher and every input of `45`, its by-level table is the ROM's, and the
differences it quotes from the ledger `56` are the ledger's."""
import os
import re
import sys
import unittest

HERE = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HERE)
sys.path.insert(0, os.path.join(ROOT, "tools"))
import analyze_behaviour_docs as B  # noqa: E402
import analyze_correlation as AC  # noqa: E402
import core_app as APP  # noqa: E402
import core_ref as R  # noqa: E402
import iface_map as I  # noqa: E402
import output_map as O  # noqa: E402

DOC = os.path.join(ROOT, "docs", "61-behaviour.md")


class BehaviourDocs(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        with open(DOC, encoding="utf-8", newline="") as fh:
            cls.text = fh.read().replace("\r\n", "\n")

    def test_the_chapter_is_current(self):
        self.assertEqual(self.text, B.doc(), "regenerate: python -I tools/analyze_behaviour_docs.py --doc docs/61-behaviour.md")

    def test_every_behaviour_is_in_the_chapter(self):
        self.assertEqual(len(AC.BEHAVIOURS), 24)
        for b in AC.BEHAVIOURS:
            self.assertIn("| %s |" % b[0], self.text, b[0])

    def test_the_frame_classes_are_exactly_the_dispatchers(self):
        names = {n for n, t in B.FRAME_CLASSES}
        self.assertEqual(len(names), 15)
        # every class the dispatcher can choose (core_app.frame_class) is described: its names are the strings returned there
        src = open(os.path.join(ROOT, "tools", "core_app.py"), encoding="utf-8").read()
        body = src[src.index("def frame_class"):src.index("def frame_class") + 2500]
        returned = set(re.findall(r'return "([a-z \-]+)"', body)) | set(re.findall(r'"([a-z \-]+)" if', body)) | set(re.findall(r'else "([a-z \-]+)"', body))
        self.assertEqual(names, returned)

    def test_every_input_of_the_interface_chapter_is_listed(self):
        for name, lo, hi, dev, who, what in I.INPUTS:
            self.assertIn("| `%s` | `$%04X` |" % (name, lo), self.text, name)
        self.assertEqual(len(I.INPUTS), 14)

    def test_the_by_level_table_is_the_roms(self):
        self.assertEqual(R.ghost_points(0), 200)
        self.assertEqual((R.fright_frames(0), R.fright_end_phase(0), R.bonus_points(12)), (255, 11, 5000))
        for lv, fr, ep, tot, bp, rt in B.level_rows():
            self.assertIn("| %d | %d | %d | %s | %d | %s |" % (lv, fr, ep, tot, bp, rt), self.text, lv)
        self.assertEqual({row[0] for row in B.level_rows()} & {16, 255}, {16, 255})

    def test_the_ledger_table_is_quoted_whole(self):
        rows = B.section3_of_ledger()
        self.assertGreaterEqual(len(rows), 10)
        for r in rows:
            self.assertIn(r, self.text)

    def test_the_state_variables_and_rules_are_those_of_the_state_chapter(self):
        self.assertIn("**20 state variables**", self.text)
        self.assertIn("**68 rules**", self.text)


if __name__ == "__main__":
    unittest.main()
